import ghidra.app.decompiler.*; import ghidra.app.script.GhidraScript; import ghidra.program.model.listing.*;
public class CollisionSlotDefs extends GhidraScript { public void run()throws Exception{DecompInterface d=new DecompInterface();d.openProgram(currentProgram);long[] xs={0x005387ceL,0x00538904L,0x00539a63L,0x00500569L,0x004f4911L,0x004e5c6fL};for(long x:xs){Function f=getFunctionContaining(toAddr(x));println("\n=== "+toAddr(x)+" "+(f==null?"<missing>":f.getName())+" ===");if(f!=null){DecompileResults r=d.decompileFunction(f,180,monitor);if(r.getDecompiledFunction()!=null)println(r.getDecompiledFunction().getC());}}d.dispose();}}
